#!/usr/bin/env python3
"""Keep the owner-approved platform directory (commit a2ce551, Oct 24, 2026) on /follow/.

The follow page is regenerated by the gateway build, which used to drop this hand-added
block. The block's exact source now lives in .github/content/platform-directory.html.src and
is inserted before the page's "start" section on every build. Idempotent.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
block = (ROOT / '.github/content/platform-directory.html.src').read_text(encoding='utf-8')
page = ROOT / 'follow/index.html'
html = page.read_text(encoding='utf-8')
anchor = '<section class="start">'
if 'class="gh-directory"' not in html:
    assert html.count(anchor) == 1, 'follow page must have exactly one start section'
    html = html.replace(anchor, block + anchor, 1)
    page.write_text(html, encoding='utf-8')
assert html.count('class="gh-directory"') == 1, 'platform directory must appear exactly once'
print('Platform directory present on /follow/.')
